  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    retained = {n['id'] for n in nodes}
    sym_count = {}
    for n in nodes:
        sym = n['symbol']
        sym_count[sym] = sym_count.get(sym, 0) + 1
    removal_order = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if n['parent'] is None:
            continue
        if n['symbol'] in required_symbols:
            continue
        child_ids = children.get(nid, [])
        if any(cid in retained for cid in child_ids):
            continue
        sym = n['symbol']
        sym_count[sym] -= 1
        if all(sym_count.get(req, 0) > 0 for req in required_symbols):
            retained.remove(nid)
            removal_order.append(nid)
        else:
            sym_count[sym] += 1
    return {'retained': sorted(retained), 'removal_order': removal_order}"
